-- Disposable database only. Fixture profiles and continuity_test helpers come from run-sql.mjs.
do $$ begin if current_setting('app.continuity_test',true) is distinct from 'isolated' then raise exception 'Disposable continuity fixture database required'; end if; end $$;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.admin_save_event_organization(null,'IT','IT Organization',true,null);
select public.admin_save_event_organization(null,'ART','Arts Organization',true,null);
select continuity_test.assert('admin creates verified organization',(select count(*)=2 from public.event_organizations));
select continuity_test.assert('admin list exposes both organizations',jsonb_array_length(public.admin_list_event_organizations())=2);
select continuity_test.denied('duplicate organization code rejected',$q$select public.admin_save_event_organization(null,'IT','Another IT',true,null)$q$,'23505');
select continuity_test.denied('organization edits reject stale timestamp',$q$select public.admin_save_event_organization((select id from public.event_organizations where code='IT'),'IT','Rename',true,null)$q$,'40001');
select public.admin_set_event_representative((select id from public.event_organizations where code='IT'),'00000000-0000-0000-0000-000000000002','2026–2027',clock_timestamp()+interval '1 year',null);
select continuity_test.assert('only one open assignment',(select count(*)=1 from public.event_organization_grants where ended_at is null));
select continuity_test.denied('invalid handover preserves original grant',$q$select public.admin_set_event_representative((select id from public.event_organizations where code='IT'),'00000000-0000-0000-0000-000000000006','2026–2027',clock_timestamp()+interval '1 year',(select id from public.event_organization_grants where ended_at is null))$q$,'23514');
select continuity_test.assert('failed replacement leaves original representative',(select representative_id='00000000-0000-0000-0000-000000000002'::uuid from public.event_organization_grants where ended_at is null));
select continuity_test.denied('stale empty assignment rejected',$q$select public.admin_set_event_representative((select id from public.event_organizations where code='IT'),'00000000-0000-0000-0000-000000000003','2026–2027',clock_timestamp()+interval '1 year',null)$q$,'40001');
select continuity_test.denied('ordinary student cannot be representative',$q$select public.admin_set_event_representative((select id from public.event_organizations where code='ART'),'00000000-0000-0000-0000-000000000005','2026–2027',clock_timestamp()+interval '1 year',null)$q$,'23514');
select continuity_test.denied('inactive profile cannot be representative',$q$select public.admin_set_event_representative((select id from public.event_organizations where code='ART'),'00000000-0000-0000-0000-000000000006','2026–2027',clock_timestamp()+interval '1 year',null)$q$,'23514');
select continuity_test.denied('expiry must be future',$q$select public.admin_set_event_representative((select id from public.event_organizations where code='ART'),'00000000-0000-0000-0000-000000000004','2026–2027',clock_timestamp()-interval '1 day',null)$q$,'23514');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select continuity_test.assert('old representative sees own context',(select count(*)=1 from public.get_my_event_organizations()));
select continuity_test.assert('representative cannot see other organization',(select count(*)=1 from public.event_organizations));
select continuity_test.denied('representative cannot self-grant',$q$select public.admin_set_event_representative(gen_random_uuid(),'00000000-0000-0000-0000-000000000002','2026–2027',clock_timestamp()+interval '1 year',null)$q$);
select continuity_test.denied('private access helper is not callable by client',$q$select private.event_organization_access(gen_random_uuid())$q$);
select continuity_test.denied('direct grant mutation denied',$q$update public.event_organization_grants set expires_at=clock_timestamp()+interval '10 years'$q$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.admin_set_event_representative((select id from public.event_organizations where code='IT'),'00000000-0000-0000-0000-000000000003','2027–2028',clock_timestamp()+interval '1 year',(select id from public.event_organization_grants where ended_at is null));
select continuity_test.assert('replacement preserves closed grant history',(select count(*)=2 from public.event_organization_grants));
select continuity_test.assert('replacement closes outgoing assignment',(select count(*)=1 from public.event_organization_grants where ended_at is not null and ended_by=auth.uid() and end_reason='replaced'));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select continuity_test.assert('outgoing representative loses context',(select count(*)=0 from public.get_my_event_organizations()));
select continuity_test.assert('outgoing representative cannot read grants',(select count(*)=0 from public.event_organization_grants));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select continuity_test.assert('successor receives organization',(select count(*)=1 from public.get_my_event_organizations()));
reset role;
update profiles set is_active=false where id='00000000-0000-0000-0000-000000000003';
set role authenticated;
select continuity_test.assert('profile deactivation removes effective access',(select count(*)=0 from public.get_my_event_organizations()));
reset role;
update profiles set is_active=true where id='00000000-0000-0000-0000-000000000003';
update event_organization_grants set starts_at=clock_timestamp()-interval '2 days',expires_at=clock_timestamp()-interval '1 day' where ended_at is null;
set role authenticated;
select continuity_test.assert('server expiry removes effective access',(select count(*)=0 from public.get_my_event_organizations()));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.admin_set_event_representative((select id from public.event_organizations where code='IT'),'00000000-0000-0000-0000-000000000002','2028–2029',clock_timestamp()+interval '1 year',(select id from public.event_organization_grants where ended_at is null));
select continuity_test.assert('expired open grant replaced safely',(select count(*)=1 from public.event_organization_grants where ended_at is null));
select public.admin_revoke_event_representative((select id from public.event_organizations where code='IT'),(select id from public.event_organization_grants where ended_at is null),'end of term');
select continuity_test.assert('explicit revoke closes assignment',(select count(*)=0 from public.event_organization_grants where ended_at is null));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',false);
select continuity_test.assert('ordinary student receives no private contexts',(select count(*)=0 from public.get_my_event_organizations()));
set role anon;
select set_config('request.jwt.claim.sub','',false);
select continuity_test.denied('anonymous contexts denied','select public.get_my_event_organizations()');
reset role;
